// Arduino Sketch
/*
  Стенд проверки К555ЛР4 (2-4И-2ИЛИ-НЕ)
  Y = НЕ( (A1&A2&A3&A4) ИЛИ (B1&B2&B3&B4) )

  Нажатие кнопки «пуск» запускает прогон всех 256 тестовых наборов.
  Если все наборы дали ожидаемый выход — загорается «годен»,
  иначе — «брак» (и в Serial выводится номер «плохого» набора).
*/

// ===== Пины =====
const uint8_t A_IN[4] = {2, 3, 4, 5};    // входы первой группы 4И
const uint8_t B_IN[4] = {6, 7, 8, 9};    // входы второй группы 4И
const uint8_t PIN_Y     = A0;            // выход микросхемы (читаем как цифровой)
const uint8_t PIN_OK    = 11;            // светодиод «Годен»
const uint8_t PIN_BAD   = 12;            // светодиод «Брак»
const uint8_t PIN_START = 10;            // кнопка «пуск» (на GND)

const unsigned long SETTLE   = 5;        // мс на установку уровней
const unsigned long LED_HOLD = 3000;     // сколько горит светодиод после теста, мс

void setup() {
  for (uint8_t i = 0; i < 4; i++) {
    pinMode(A_IN[i], OUTPUT);
    pinMode(B_IN[i], OUTPUT);
  }
  pinMode(PIN_Y, INPUT);                 // A0 как цифровой вход

  pinMode(PIN_OK,  OUTPUT);
  pinMode(PIN_BAD, OUTPUT);
  pinMode(PIN_START, INPUT_PULLUP);      // кнопка замыкает пин на GND

  Serial.begin(9600);
  Serial.println(F("Стенд К555ЛР4 готов. Нажмите ПУСК."));
}

// Подать тестовый набор на входы ИМС
void applyVector(uint8_t codeA, uint8_t codeB) {
  for (uint8_t i = 0; i < 4; i++) {
    digitalWrite(A_IN[i], (codeA >> i) & 1);
    digitalWrite(B_IN[i], (codeB >> i) & 1);
  }
  delay(SETTLE);
}

// Эталон по таблице истинности 2-4И-2ИЛИ-НЕ
bool expectY(uint8_t codeA, uint8_t codeB) {
  bool andA = (codeA == 0b1111);         // первая 4И
  bool andB = (codeB == 0b1111);         // вторая 4И
  return !(andA || andB);                // 2ИЛИ-НЕ
}

bool runTest() {
  for (uint8_t codeA = 0; codeA <= 15; codeA++) {
    for (uint8_t codeB = 0; codeB <= 15; codeB++) {
      applyVector(codeA, codeB);
      bool y = digitalRead(PIN_Y);       // читаем A0 в цифровом режиме (0/1)

      if (y != expectY(codeA, codeB)) {
        Serial.print(F("Брак: A="));
        Serial.print(codeA, BIN);
        Serial.print(F(" B="));
        Serial.print(codeB, BIN);
        Serial.print(F(" Y="));
        Serial.print(y);
        Serial.print(F(" (ожидалось "));
        Serial.print(expectY(codeA, codeB));
        Serial.println(F(")"));
        return false;
      }
    }
  }
  return true;
}

void loop() {
  // Оба светодиода погашены, ждём пуск
  digitalWrite(PIN_OK,  LOW);
  digitalWrite(PIN_BAD, LOW);

  if (digitalRead(PIN_START) == LOW) {   // кнопка нажата
    delay(30);                           // антидребезг
    if (digitalRead(PIN_START) == LOW) {
      bool ok = runTest();

      digitalWrite(ok ? PIN_OK : PIN_BAD, HIGH);  // зажигаем вердикт
      Serial.println(ok ? F("ИМС ГОДНА") : F("ИМС БРАК"));

      // Ждём отпускания кнопки, затем держим светодиод ещё LED_HOLD мс
      while (digitalRead(PIN_START) == LOW) {}
      delay(LED_HOLD);
    }
  }
}
